"""Blocked recovery fixture in Chromium production App; controlled clock/render scheduling.
Initial shore poses/roster are explicit fixtures; no claim of normal campaign victory.
"""
import json,os,shutil
from pathlib import Path
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];expected=os.environ.get('HONRO_EXPECT_WATER_DEADLOCK')=='1';label='before-browser'if expected else'after-browser';out=R/'_local/reports/water-recovery-blocked-app'/label;out.mkdir(parents=True,exist_ok=True)
run_setup="""()=>{const a=HonroApp,e=a.engine,C=HONRO_CORE;let ticks=0,frames=0,ready=0,firstReturn=null,now=performance.now();const originalFrame=window.waterProductionFrame,originalRender=a.scene.render.bind(a.scene);a.frame=()=>{};a.scene.render=()=>{};a.prev=now;Object.defineProperty(performance,'now',{value:()=>now,configurable:true});const tick=e.tick.bind(e);e.tick=dt=>{ticks++;const r=tick(dt);for(const u of e.heroesAlive())if(!u.waterRecovery&&u.x<=4100&&u.y>=2820&&!firstReturn)firstReturn={tick:ticks,id:u.id,x:u.x,y:u.y,acted:u.acted,moveLeft:u.moveLeft,supported:C.validTerrainContactPose(e.b.terrain,u)};return r;};window.waterRun=n=>{while(ticks<n&&frames<6000&&!a.done){now+=1000/120;originalFrame(now);frames++;if(a.lastError)throw Error(a.lastError);for(let i=0;i<20&&a.dialogue;i++)HonroStory.finish(a);if(e.canAct())ready++;}const heroes=e.heroesAlive();return{ticks,frames,ready,firstReturn,round:e.b.round,phase:e.b.phase,softlocked:e.b.phase==='aim'&&heroes.length>0&&heroes.every(u=>u.waterRecovery)&&!e.canAct(),heroes:heroes.map(u=>({id:u.id,x:u.x,y:u.y,hp:u.hp,acted:u.acted,moveLeft:u.moveLeft,pending:!!u.waterRecovery}))};};window.waterRender=()=>{a.scene.render=originalRender;a.turnNotice=null;const banner=document.getElementById('turn-banner');if(banner)banner.hidden=true;Object.assign(a.scene,{x:4000,y:2790,scale:.8,manual:true,goalFocus:null,storyTween:null,cinematic:null});originalRender(e,0,'',.6,false,0);a.updateHUD(true);};}"""
with sync_playwright()as pw:
 browser=pw.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox','--disable-dev-shm-usage']);p=browser.new_page(viewport={'width':1440,'height':900});errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
 p.goto('http://127.0.0.1:8842/HONRO.html');p.wait_for_function('window.HonroApp && window.HonroCampaignLoader',timeout=90000)
 profile=json.loads((R/'_local/reports/water-recovery-blocked-app/browser-profile.json').read_text())
 entry=p.evaluate('''async profile=>{await HonroCampaignLoader.ensureStage(5);const a=HonroApp;a.profile=profile;a.debugMode=false;a.profile.settings.sound=false;a.profile.settings.music=false;a.launch(5);for(let i=0;i<20&&a.dialogue;i++)HonroStory.finish(a);a.close();window.waterProductionFrame=a.frame.bind(a);a.frame=()=>{};const e=a.engine,b=e.b,heroes=e.heroesAlive(),w=b.waters.find(w=>w.id==='stage5-plunge-pool'),blockers=[e.unit('s5-entry-hound'),e.unit('s5-cave-hound')];b.units=b.units.filter(u=>heroes.includes(u)||blockers.includes(u)||u.honroObjectiveTarget);for(const[i,u]of blockers.entries())Object.assign(u,{x:w.policy.shores.left[i].x,y:2860,fixed:true,awake:true,aggroUntil:999});for(const[i,u]of heroes.entries())Object.assign(u,{x:4200+i*70,y:3000,waterEntrySides:{[w.id]:'left'},acted:false,vx:0,vy:0});const before=heroes.map(u=>({id:u.id,hp:u.hp,maxHp:u.maxHp}));e.tick(0);return{before,after:heroes.map(u=>({id:u.id,hp:u.hp,acted:u.acted,moveLeft:u.moveLeft,pending:!!u.waterRecovery}))};}''',profile)
 p.wait_for_function('HonroAuthoredFarArt.ready(5)',timeout=90000);p.evaluate(run_setup);first=p.evaluate('waterRun(240)');saved=p.evaluate('''()=>{HonroApp.stopBattle();return HonroApp.profile.honroBattle.units.filter(u=>u.side===0).map(u=>({id:u.id,hp:u.hp,pending:!!u.waterRecovery}));}''')
 p.reload();p.wait_for_function('window.HonroApp && window.HonroCampaignLoader',timeout=90000);p.evaluate('''async()=>{await HonroCampaignLoader.ensureStage(5);HonroApp.continue();for(let i=0;i<20&&HonroApp.dialogue;i++)HonroStory.finish(HonroApp);HonroApp.close();window.waterProductionFrame=HonroApp.frame.bind(HonroApp);HonroApp.frame=()=>{};}''');p.wait_for_function('HonroAuthoredFarArt.ready(5)',timeout=90000);p.evaluate(run_setup);second=p.evaluate('waterRun(961)')
 assert first['ticks']+second['ticks']>=1201
 assert second['softlocked']==expected
 if not expected:assert first['firstReturn']['supported']and first['firstReturn']['acted']and first['firstReturn']['moveLeft']==0 and second['ready']>0
 for width,height in[(1440,900),(390,844)]:
  p.set_viewport_size({'width':width,'height':height});p.wait_for_timeout(100);p.evaluate('waterRender()');p.screenshot(path=str(out/f'blocked-shore-{width}.png'))
 assert not errors,errors
 result={'scope':__doc__,'expectedBlocked':expected,'entry':entry,'beforeContinue':first,'saved':saved,'afterReloadContinue':second,'errors':errors};(out/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2));print(json.dumps(result,ensure_ascii=False));browser.close()
